INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','mcq','A 45-year-old man is admitted with vomiting and diarrhoea for 3 days. Serum creatinine rises from 0.9 to 1.4 mg/dL within 48 hours. According to KDIGO criteria, how is this classified?','["A. AKI Stage 1","B. AKI Stage 2","C. AKI Stage 3","D. No AKI — within normal limits"]','A','KDIGO defines AKI as a rise in serum creatinine ≥0.3 mg/dL within 48 h (Stage 1). Here the rise is 0.5 mg/dL, meeting Stage 1 criteria. Stage 2 requires ≥2× baseline; Stage 3 requires ≥3× baseline or creatinine ≥4.0 mg/dL.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','mcq','A 60-year-old woman in the ICU develops oliguria (<0.5 mL/kg/h for 12 hours) and her serum creatinine doubles from baseline. Which KDIGO AKI stage does this represent?','["A. Stage 1","B. Stage 2","C. Stage 3","D. Acute-on-chronic kidney disease"]','B','KDIGO AKI Stage 2 is defined by serum creatinine 2–2.9× baseline OR urine output <0.5 mL/kg/h for ≥12 hours. This patient meets both urine output and creatinine criteria for Stage 2.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','mcq','A 72-year-old man develops AKI after coronary angiography. Urine sodium is 12 mEq/L and fractional excretion of sodium (FENa) is 0.6%. What is the most likely aetiology?','["A. Acute tubular necrosis","B. Glomerulonephritis","C. Prerenal azotemia / contrast nephropathy with intact tubular function","D. Urinary tract obstruction"]','C','FENa <1% indicates intact tubular sodium reabsorption, consistent with prerenal azotemia or early contrast nephropathy where tubular function is preserved. ATN typically shows FENa >2% with muddy brown casts. Obstruction would show variable FENa.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','hard','mcq','A 58-year-old man with septic shock develops AKI Stage 3. Despite fluid resuscitation, he remains oliguric with serum potassium 6.8 mEq/L, bicarbonate 10 mEq/L, and pulmonary oedema on CXR. What is the most appropriate next step?','["A. Increase IV fluid rate to 500 mL/h","B. Administer furosemide 200 mg IV bolus","C. Administer sodium bicarbonate 8.4% 50 mL IV","D. Initiate renal replacement therapy"]','D','Absolute indications for RRT in AKI include refractory hyperkalaemia, severe metabolic acidosis unresponsive to medical management, refractory pulmonary oedema, and uraemic complications. This patient has multiple indications. Fluids are contraindicated given pulmonary oedema; furosemide is unlikely to work in established Stage 3 AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','mcq','Which of the following urinary findings is most characteristic of acute tubular necrosis (ATN)?','["A. Muddy brown granular casts","B. Red cell casts","C. White cell casts","D. Fatty casts (oval fat bodies)"]','A','Muddy brown granular casts are pathognomonic of ATN, resulting from sloughed tubular epithelial cells. Red cell casts indicate glomerulonephritis; white cell casts suggest pyelonephritis or interstitial nephritis; fatty casts are seen in nephrotic syndrome.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','mcq','A 35-year-old woman is started on gentamicin for Gram-negative sepsis. On day 5, her creatinine rises from 0.8 to 2.4 mg/dL. Which pattern of urinary sediment would most support aminoglycoside nephrotoxicity?','["A. Red cell casts with proteinuria","B. Granular casts with renal tubular epithelial cells","C. Waxy casts and broad casts","D. Hyaline casts only"]','B','Aminoglycoside nephrotoxicity causes proximal tubular injury (ATN). The urinary sediment shows granular (muddy brown) casts and renal tubular epithelial cells. Aminoglycosides accumulate in proximal tubular cells via megalin-mediated endocytosis causing direct toxicity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','mcq','According to KDIGO nutrition guidelines, what protein intake is recommended for a non-catabolic AKI patient not requiring dialysis?','["A. 0.4–0.6 g/kg/day","B. 1.5–2.0 g/kg/day","C. 0.8–1.0 g/kg/day","D. 2.0–2.5 g/kg/day"]','C','KDIGO recommends 0.8–1.0 g/kg/day protein for non-catabolic AKI patients not on dialysis, 1.0–1.5 g/kg/day for those on dialysis, and up to 1.7 g/kg/day for hypercatabolic patients on CRRT. Total energy intake should be 20–30 kcal/kg/day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','hard','mcq','A 50-year-old man with AKI has urine osmolality of 290 mOsm/kg, urine sodium of 55 mEq/L, and granular casts on microscopy. His serum creatinine is 5.8 mg/dL. Which feature most distinguishes established ATN from prerenal azotemia?','["A. Elevated serum creatinine","B. Oliguria <400 mL/day","C. BUN:creatinine ratio >20:1","D. Urine osmolality close to plasma with high urine sodium and granular casts"]','D','In ATN, tubular function is lost: urine osmolality approximates plasma (~290 mOsm/kg), urine sodium is high (>40 mEq/L), FENa >2%, and muddy brown granular casts are present. In prerenal azotemia, tubules concentrate urine (osmolality >500), reabsorb sodium (UNa <20, FENa <1%), and casts are absent. BUN:Cr >20 supports prerenal, not ATN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','easy','mcq','A patient with AKI is found to have bilateral hydronephrosis on ultrasound. What category of AKI does this most likely represent?','["A. Postrenal AKI","B. Prerenal AKI","C. Intrinsic renal AKI","D. Hepatorenal syndrome"]','A','Bilateral hydronephrosis indicates obstruction of urinary outflow — postrenal AKI. Common causes include bilateral ureteric obstruction, bladder outlet obstruction (BPH, prostate cancer), or obstruction of a single functioning kidney. Relief of obstruction is the treatment.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acute Kidney Injury — Diagnosis & Management','medium','mcq','A 67-year-old man with CKD stage 3 (baseline creatinine 1.8 mg/dL) is admitted with dehydration. His creatinine is now 3.6 mg/dL. How should this be classified?','["A. CKD progression only — no AKI","B. AKI Stage 2 superimposed on CKD","C. AKI Stage 3","D. End-stage renal disease"]','B','AKI can be superimposed on CKD. Current creatinine 3.6 vs baseline 1.8 mg/dL = 2× baseline, meeting KDIGO Stage 2 criteria (2–2.9× baseline). This is AKI-on-CKD, a common and clinically important diagnosis. Patients with CKD are at highest risk for AKI.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','mcq','A 55-year-old diabetic woman has an eGFR of 42 mL/min/1.73m² persisting for >3 months with albuminuria. Which CKD stage does this represent?','["A. CKD Stage G3b","B. CKD Stage G2","C. CKD Stage G4","D. CKD Stage G5"]','A','KDIGO CKD staging by eGFR: G1 ≥90, G2 60–89, G3a 45–59, G3b 30–44, G4 15–29, G5 <15 mL/min/1.73m². An eGFR of 42 falls in G3b. The diagnosis requires abnormalities present for >3 months.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','mcq','A 63-year-old man with CKD G4 (eGFR 22) has haemoglobin 9.2 g/dL, serum ferritin 280 ng/mL, and transferrin saturation 28%. What is the most appropriate initial treatment for his anaemia?','["A. Blood transfusion immediately","B. Erythropoiesis-stimulating agent (ESA) therapy","C. Oral iron supplementation alone","D. Vitamin B12 injections"]','B','Anaemia of CKD is primarily due to reduced erythropoietin production. When iron stores are adequate (ferritin >200, TSAT >20%), ESA therapy (e.g., epoetin alfa or darbepoetin) is indicated. Target Hb is 10–12 g/dL — avoid >13 g/dL due to cardiovascular risk. Iron should be optimised first if deficient.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','mcq','A patient with CKD has serum phosphate 2.1 mmol/L, PTH 320 pg/mL, and calcium 2.05 mmol/L. Which condition best describes this constellation?','["A. Primary hyperparathyroidism","B. Hypoparathyroidism","C. CKD-mineral and bone disorder (CKD-MBD)","D. Hypervitaminosis D"]','C','CKD-MBD is characterised by hyperphosphataemia, hypocalcaemia, elevated PTH (secondary hyperparathyroidism), and reduced calcitriol (1,25-OH vitamin D) due to decreased 1α-hydroxylase activity. Management includes phosphate binders, active vitamin D analogues (calcitriol/alfacalcidol), and calcimimetics (cinacalcet).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','hard','mcq','A 70-year-old woman with CKD G5 (eGFR 12) is being prepared for renal replacement therapy. Her BP is 158/96 mmHg despite three antihypertensives. Which antihypertensive class has the strongest evidence for slowing CKD progression in proteinuric kidney disease?','["A. Beta-blockers","B. Calcium channel blockers","C. Loop diuretics","D. ACE inhibitors or ARBs"]','D','ACE inhibitors and ARBs reduce intraglomerular hypertension by dilating the efferent arteriole, thereby reducing proteinuria and slowing CKD progression. They are first-line for all proteinuric CKD. They should not be combined (dual blockade increases adverse effects). SGLT2 inhibitors also have emerging evidence for CKD progression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','mcq','A patient with CKD is counselled on dietary modification. Which dietary restriction is most critical in CKD Stage 4?','["A. Phosphate and potassium restriction","B. High protein diet to prevent malnutrition","C. Increased sodium intake for blood pressure","D. Unrestricted fluid intake"]','A','In CKD Stage 4, dietary phosphate restriction (to <800 mg/day) helps prevent CKD-MBD, and potassium restriction reduces risk of hyperkalaemia. Protein is modestly restricted (0.6–0.8 g/kg/day) to slow progression. Sodium restriction helps control blood pressure and fluid balance.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','mcq','Which finding on renal ultrasound most supports a diagnosis of CKD rather than AKI?','["A. Normal-sized echogenic kidneys","B. Bilaterally small echogenic kidneys with cortical thinning","C. Enlarged kidneys with loss of corticomedullary differentiation","D. Unilateral hydronephrosis"]','B','Small, echogenic kidneys with cortical thinning on ultrasound indicate chronic scarring and fibrosis, hallmarks of CKD. In AKI, kidneys are often normal-sized or enlarged. Polycystic kidney disease causes enlarged kidneys with cysts. Unilateral hydronephrosis suggests obstruction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','mcq','A 48-year-old woman with CKD G3b is found to have serum bicarbonate of 18 mEq/L. What is the rationale for treating this metabolic acidosis?','["A. It increases the risk of cardiac arrhythmias","B. It causes hyponatraemia","C. Acidosis accelerates CKD progression by promoting protein catabolism and tubulointerstitial injury","D. It reduces phosphate excretion"]','C','Metabolic acidosis in CKD accelerates progression by stimulating ammoniagenesis, increasing complement activation, and promoting protein catabolism and muscle wasting. KDIGO recommends treating with oral sodium bicarbonate to maintain serum bicarbonate >22 mEq/L. Target is 22–26 mEq/L.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','hard','mcq','A 65-year-old man with CKD G4 and type 2 diabetes is started on an SGLT2 inhibitor. His eGFR drops from 26 to 22 mL/min/1.73m² over 2 weeks. What is the most appropriate action?','["A. Stop SGLT2 inhibitor immediately — it is causing AKI","B. Add an ACE inhibitor to counteract the decline","C. Increase fluid intake to 3 L/day","D. Continue SGLT2 inhibitor — the initial eGFR dip is expected and reflects haemodynamic effect, not structural injury"]','D','SGLT2 inhibitors cause an initial reversible eGFR dip of ~3–5 mL/min due to haemodynamic effects (reduced glomerular hyperfiltration). This is analogous to the initial eGFR dip seen with ACE inhibitors and is not a reason to stop therapy. Long-term, SGLT2 inhibitors slow CKD progression. The drug should be stopped if eGFR falls below 20 or the decline is >30%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','easy','mcq','A CKD patient develops pruritus and a pericardial rub. What does the pericardial rub most likely indicate?','["A. Uraemic pericarditis requiring urgent dialysis","B. Viral pericarditis — start NSAIDs","C. Cardiac tamponade from fluid overload","D. Autoimmune pericarditis from CKD"]','A','Uraemic pericarditis is a serious complication of advanced CKD/uraemia, characterised by a pericardial friction rub, chest pain, and fever. It is an indication for urgent dialysis. NSAIDs should be avoided (nephrotoxic). Pruritus is also a uraemic symptom.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Chronic Kidney Disease — Stages & Management','medium','mcq','Which formula is currently preferred for estimating GFR in CKD monitoring?','["A. Cockcroft-Gault using total body weight","B. CKD-EPI creatinine equation","C. MDRD-4 variable equation","D. 24-hour creatinine clearance only"]','B','The CKD-EPI (Chronic Kidney Disease Epidemiology Collaboration) creatinine equation is currently preferred for estimating GFR as it is more accurate than MDRD, particularly at higher GFR values (>60 mL/min). Cystatin C-based and combined equations offer additional accuracy. 24-hour urine creatinine clearance is cumbersome and less practical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','mcq','A 25-year-old man presents with periorbital oedema, proteinuria 5.8 g/24h, serum albumin 1.8 g/dL, and hyperlipidaemia. Which diagnosis best fits this clinical picture?','["A. Nephrotic syndrome","B. Nephritic syndrome","C. Acute glomerulonephritis","D. Chronic pyelonephritis"]','A','Nephrotic syndrome is defined by the triad: heavy proteinuria (>3.5 g/24h in adults), hypoalbuminaemia (<3.5 g/dL), and oedema. Hyperlipidaemia and lipiduria are also characteristic. The liver upregulates lipoprotein synthesis in response to low oncotic pressure. This patient meets all criteria.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','mcq','A 4-year-old child with nephrotic syndrome is started on prednisolone and achieves complete remission within 4 weeks. What is the most likely histological diagnosis?','["A. Focal segmental glomerulosclerosis","B. Minimal change disease","C. Membranous nephropathy","D. IgA nephropathy"]','B','Minimal change disease (MCD) is the most common cause of nephrotic syndrome in children (80% of cases) and is characterised by its dramatic response to steroids. On light microscopy it appears normal; electron microscopy shows diffuse podocyte foot process effacement. FSGS is steroid-resistant; membranous is commonest in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','mcq','A 52-year-old woman with membranous nephropathy has proteinuria 6 g/24h and serum albumin 2.2 g/dL. She develops sudden-onset right calf pain and swelling. What complication has occurred?','["A. Cellulitis from skin breakdown","B. Arterial embolism from hypercoagulable state","C. Deep vein thrombosis due to nephrotic hypercoagulability","D. Lymphoedema from hypoalbuminaemia"]','C','Nephrotic syndrome predisposes to thrombosis due to: urinary loss of anticoagulants (antithrombin III, protein C, S), elevated fibrinogen, platelet hyperaggregability, and increased clotting factors. Renal vein thrombosis is classic (particularly in membranous nephropathy); DVT and pulmonary embolism also occur. Anticoagulation is indicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','hard','mcq','A 38-year-old man with HIV develops nephrotic-range proteinuria. Renal biopsy shows segmental sclerosis with endocapillary proliferation and collapse of glomerular tufts. What is the most likely diagnosis?','["A. Minimal change disease","B. Membranous nephropathy","C. IgA nephropathy","D. HIV-associated nephropathy (HIVAN)"]','D','HIVAN classically presents with heavy proteinuria, rapid progression to ESRD, and a collapsing variant of FSGS on biopsy (collapsing glomerulopathy). It predominantly affects patients of African descent. Electron microscopy shows tubuloreticular inclusions. Treatment is with antiretroviral therapy ± ACE inhibitors.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','mcq','A patient with nephrotic syndrome develops frothy urine, periorbital puffiness, and bilateral pitting leg oedema. What is the immediate management priority?','["A. Loop diuretics (furosemide) for oedema with dietary sodium restriction","B. High-dose IV albumin alone","C. Haemodialysis","D. High-protein diet to replace urinary losses"]','A','Initial management of nephrotic oedema includes loop diuretics (furosemide) and strict dietary sodium restriction (<2 g/day). IV albumin alone is not effective long-term but may be used with furosemide for resistant oedema. High-protein diet increases proteinuria and is contraindicated. Address the underlying cause with immunosuppression.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','mcq','A 60-year-old man with membranous nephropathy is found to have anti-PLA2R antibodies positive at high titre. What does this finding indicate?','["A. Secondary membranous nephropathy from malignancy","B. Primary (idiopathic) membranous nephropathy — anti-PLA2R is a specific marker","C. Minimal change disease variant","D. Lupus membranous nephropathy (class V)"]','B','Anti-phospholipase A2 receptor (anti-PLA2R) antibodies are present in ~70–80% of primary (idiopathic) membranous nephropathy. They are rarely found in secondary causes (lupus, malignancy, hepatitis B). Anti-PLA2R titres correlate with disease activity and can predict remission and relapse.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','mcq','A child with steroid-resistant nephrotic syndrome has a renal biopsy showing segmental sclerosis. Genetic testing reveals a NPHS2 mutation. What is the most appropriate management?','["A. Increase prednisolone dose","B. Add cyclophosphamide","C. Refer for renal transplant evaluation — genetic FSGS does not respond to immunosuppression","D. Mycophenolate mofetil"]','C','Mutations in NPHS2 (encoding podocin) cause autosomal recessive steroid-resistant FSGS. Genetic forms do not respond to immunosuppression. These patients progress to ESRD and require renal transplantation. Non-genetic FSGS may respond to calcineurin inhibitors (tacrolimus/cyclosporine).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','hard','mcq','A 45-year-old woman with primary membranous nephropathy has persistent proteinuria >8 g/24h despite 6 months of conservative therapy. She has no contraindications to immunosuppression. Which treatment regimen has the best evidence?','["A. High-dose prednisolone monotherapy","B. Mycophenolate mofetil alone","C. Azathioprine alone","D. Alternating chlorambucil/prednisolone (Ponticelli regimen) or rituximab"]','D','The modified Ponticelli regimen (alternating monthly cycles of IV methylprednisolone + oral prednisolone and oral chlorambucil for 6 months) has the best long-term evidence for primary membranous nephropathy. Rituximab (anti-CD20) is increasingly used as a less toxic alternative. Prednisolone monotherapy is ineffective in membranous nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','easy','mcq','Which serum finding is pathognomonic of nephrotic syndrome?','["A. Serum albumin <3.5 g/dL with urinary protein >3.5 g/day","B. Serum creatinine >2.0 mg/dL","C. Haematuria with red cell casts","D. Complement C3 low with ANA positive"]','A','The nephrotic syndrome is defined by the combination of heavy proteinuria (>3.5 g/24h or protein:creatinine ratio >3.5), hypoalbuminaemia (<3.5 g/dL), and oedema. Haematuria and red cell casts are nephritic features. Low complement is seen in lupus nephritis or MPGN.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephrotic Syndrome — Clinical Management','medium','mcq','A 30-year-old woman with SLE develops proteinuria 4 g/24h, serum albumin 2.8 g/dL, and biopsy shows thickened glomerular basement membrane with subepithelial deposits. What ISN classification applies?','["A. Class III lupus nephritis","B. Class V lupus nephritis (membranous)","C. Class IV lupus nephritis","D. Class I lupus nephritis"]','B','ISN Class V lupus nephritis (membranous) presents with nephrotic syndrome, subepithelial immune deposits on biopsy, and a relatively indolent course compared to Class III/IV. Class IV (diffuse proliferative) is the most severe form presenting with nephritic features. Treatment of Class V includes ACE inhibitors ± mycophenolate.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','mcq','A 10-year-old boy presents 2 weeks after a sore throat with haematuria, periorbital oedema, hypertension, and oliguria. C3 is low. What is the most likely diagnosis?','["A. Post-streptococcal glomerulonephritis","B. IgA nephropathy","C. Alport syndrome","D. Thin basement membrane disease"]','A','Post-streptococcal GN classically occurs 1–3 weeks after pharyngitis (or 3–6 weeks after skin infection). It presents with the full nephritic syndrome: haematuria (coca-cola urine), hypertension, oedema, and oliguria. C3 is depressed (low) during active disease due to complement activation via the alternative pathway. It is usually self-limiting.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','mcq','A 28-year-old man with recurrent episodes of macroscopic haematuria within 24–72 hours of upper respiratory infections has renal biopsy showing mesangial IgA deposits. What is the diagnosis?','["A. Post-streptococcal GN","B. IgA nephropathy (Bergers disease)","C. Thin basement membrane nephropathy","D. Anti-GBM disease"]','B','IgA nephropathy (Berger''''s disease) is the most common primary glomerulonephritis worldwide. Macroscopic haematuria occurs synpharyngitically (concurrent with, not after, URTI — distinguishing it from post-streptococcal GN). Biopsy shows mesangial IgA deposits. Complement levels are typically normal.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','mcq','A 45-year-old man presents with rapidly progressive renal failure, haemoptysis, haematuria, and anti-GBM antibodies positive. Chest X-ray shows bilateral pulmonary infiltrates. What is the most likely diagnosis?','["A. Wegeners granulomatosis (GPA)","B. Goodpastures syndrome","C. Goodpastures syndrome","D. Churg-Strauss syndrome"]','C','Goodpasture''''s syndrome (anti-GBM disease) presents with pulmonary haemorrhage + rapidly progressive glomerulonephritis. Anti-GBM antibodies target the NC1 domain of type IV collagen in the GBM and alveolar basement membrane. Biopsy shows linear IgG deposits on immunofluorescence. Treatment: plasmapheresis + cyclophosphamide + steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','hard','mcq','A 35-year-old woman with SLE has creatinine rising to 3.2 mg/dL over 3 weeks, haematuria with red cell casts, proteinuria 4 g/24h, C3 and C4 both low, and ANA/anti-dsDNA positive. Renal biopsy shows diffuse mesangial and endocapillary proliferation with subendothelial deposits. What ISN class is this?','["A. ISN Class II","B. ISN Class III","C. ISN Class V","D. ISN Class IV"]','D','ISN Class IV (diffuse proliferative lupus nephritis) is the most common and most severe form, affecting >50% of glomeruli. Features include active urinary sediment, proteinuria, rapid decline in renal function, low C3/C4, and positive anti-dsDNA. Biopsy shows wire-loop deposits (subendothelial). Treatment: mycophenolate mofetil (or IV cyclophosphamide) + high-dose steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','mcq','Which complement pattern is most characteristic of post-streptococcal glomerulonephritis?','["A. Low C3, normal C4","B. Low C3 and C4","C. Normal C3 and C4","D. High C3 and C4"]','A','Post-streptococcal GN activates the alternative complement pathway, leading to low C3 with normal C4. In contrast, lupus nephritis (classical pathway) shows low C3 AND low C4. MPGN Type II (dense deposit disease) also shows low C3 via C3 nephritic factor. Normal complement is seen in IgA nephropathy and anti-GBM disease.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','mcq','A 22-year-old man with haematuria and sensorineural deafness has a family history of renal failure. Renal biopsy electron microscopy shows irregular thinning and splitting of the GBM (''''basket weave'''' appearance). What is the diagnosis?','["A. Thin basement membrane disease","B. Alport syndrome","C. IgA nephropathy","D. Post-streptococcal GN"]','B','Alport syndrome is an X-linked (85%) or autosomal recessive disorder of type IV collagen (COL4A3/4/5 mutations) causing progressive nephritis, sensorineural deafness, and ocular abnormalities (anterior lenticonus). EM shows characteristic ''''basket weave'''' or lamellated splitting of the GBM. It progresses to ESRD, typically by age 20–30 in males.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','mcq','A 55-year-old woman presents with haematuria, red cell casts, hypertension, and oliguria. C3 is 0.45 g/L (low). ANCA is positive (c-ANCA/anti-PR3). What is the most appropriate initial treatment?','["A. Oral prednisolone alone","B. Plasma exchange alone","C. High-dose IV methylprednisolone + cyclophosphamide","D. ACE inhibitor and close monitoring"]','C','ANCA-associated vasculitis (Granulomatosis with Polyangiitis — GPA, if c-ANCA/anti-PR3) presenting with rapidly progressive GN requires aggressive treatment: high-dose IV methylprednisolone pulse + cyclophosphamide (or rituximab). Plasma exchange is added if pulmonary haemorrhage or dialysis-dependent. Untreated, it leads to irreversible renal failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','hard','mcq','A 40-year-old man is noted to have serum creatinine of 4.5 mg/dL that has risen from 1.0 mg/dL over 6 weeks. Renal biopsy shows >50% glomerular crescents on light microscopy. What is the histological pattern?','["A. Focal segmental glomerulosclerosis","B. Membranous glomerulopathy","C. Minimal change disease","D. Rapidly progressive (crescentic) glomerulonephritis"]','D','Rapidly progressive GN (RPGN) is defined by >50% glomeruli with crescents on biopsy, causing rapid loss of renal function. It has 3 immunological categories: Type I (anti-GBM/linear IgG); Type II (immune complex-mediated, e.g., lupus, post-infectious); Type III (pauci-immune/ANCA-associated). All require urgent aggressive immunosuppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','easy','mcq','Which clinical feature most distinguishes nephritic from nephrotic syndrome?','["A. Haematuria with red cell casts and hypertension","B. Massive proteinuria >3.5 g/24h","C. Hypoalbuminaemia <2.5 g/dL","D. Bilateral pitting ankle oedema"]','A','Nephritic syndrome is characterised by haematuria (often macroscopic), red cell casts (pathognomonic of glomerular bleeding), hypertension, and oliguria with variable proteinuria. Nephrotic syndrome is defined by heavy proteinuria, hypoalbuminaemia, oedema, and hyperlipidaemia without haematuria predominating.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Nephritic Syndrome — Clinical Management','medium','mcq','A 7-year-old girl presents with haematuria, proteinuria, and hypertension 3 weeks after impetigo. Throat and skin swabs grow Group A Streptococcus. What is the treatment?','["A. High-dose prednisolone 2 mg/kg/day","B. Penicillin V for 10 days to eradicate streptococcal infection, supportive care for GN","C. Cyclophosphamide + steroids","D. Plasma exchange"]','B','Post-streptococcal GN treatment is primarily supportive — antihypertensives, fluid/sodium restriction, and diuretics for oedema. Penicillin/amoxicillin eradicates residual streptococcal infection and prevents spread but does not alter the course of GN (immune-mediated injury is already established). Immunosuppression is not indicated. Prognosis is excellent in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','mcq','A 50-year-old man with CKD Stage 3 (eGFR 45) and proteinuria 1.8 g/24h has BP 155/95. Which antihypertensive is the most appropriate first choice?','["A. Ramipril 5 mg daily","B. Amlodipine 5 mg daily","C. Atenolol 50 mg daily","D. Hydrochlorothiazide 25 mg daily"]','A','ACE inhibitors (e.g., ramipril) and ARBs are first-line for hypertension in CKD with proteinuria. They reduce intraglomerular pressure, decrease proteinuria by 30–50%, and slow CKD progression independent of blood pressure effects. Monitor potassium and creatinine after initiation. Thiazides lose efficacy when eGFR <30.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','mcq','A 35-year-old woman presents with resistant hypertension (BP 172/108 despite 3 antihypertensives), a bruit over the right flank, and hypokalaemia. Renal angiography shows >70% stenosis of the right renal artery. What is the pathophysiology?','["A. Primary aldosteronism","B. Renovascular hypertension — renin-angiotensin system activation","C. Phaeochromocytoma","D. Cushings syndrome"]','B','Renal artery stenosis (atherosclerotic or fibromuscular dysplasia) reduces renal perfusion, activating renin release and the RAAS. Elevated angiotensin II causes hypertension and aldosterone-driven hypokalaemia. A renal bruit is a clinical clue. Duplex ultrasound or CT angiography confirms diagnosis. Treatment: percutaneous renal artery angioplasty ± stenting (fibromuscular); medical therapy for atherosclerotic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','mcq','A 62-year-old man with longstanding poorly controlled hypertension develops AKI after starting an ACE inhibitor. Renal imaging shows bilateral renal artery stenosis. Why did his creatinine rise?','["A. ACE inhibitor causes direct tubular toxicity","B. ACE inhibitor caused allergic interstitial nephritis","C. ACE inhibitor dilates efferent arteriole reducing intraglomerular pressure in kidneys already dependent on angiotensin II for filtration","D. ACE inhibitor raised blood pressure paradoxically"]','C','In bilateral renal artery stenosis (or stenosis of a single functioning kidney), the kidney depends on angiotensin II-mediated efferent arteriolar constriction to maintain GFR. ACE inhibitors block this, causing a critical drop in GFR. This is a contraindication for ACE inhibitors/ARBs in bilateral RAS. Renal function should be checked 1–2 weeks after starting these drugs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','hard','mcq','A 68-year-old man with hypertension and CKD presents with sudden onset pulmonary oedema despite normal LV function (''''flash pulmonary oedema''''). BP is 210/120 mmHg. Renal function is markedly impaired. What syndrome should be strongly suspected?','["A. Hypertensive urgency","B. Left ventricular failure from hypertension","C. Pulmonary embolism","D. Bilateral renal artery stenosis causing Pickering syndrome"]','D','Pickering syndrome describes episodic flash pulmonary oedema in the context of bilateral renal artery stenosis (or stenosis of a single functioning kidney). The kidneys cannot excrete sodium, leading to volume overload and pulmonary oedema. Hypertension is severe and resistant. Renal revascularisation can dramatically improve this syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','mcq','A patient with CKD has an estimated GFR of 28 mL/min. Which antihypertensive should be used with caution due to reduced efficacy at this GFR level?','["A. Thiazide diuretics","B. ACE inhibitors","C. Amlodipine","D. Carvedilol"]','A','Thiazide diuretics (e.g., hydrochlorothiazide, bendroflumethiazide) lose their natriuretic and antihypertensive efficacy when GFR falls below 30 mL/min/1.73m². Loop diuretics (furosemide, bumetanide) should be used instead in advanced CKD. ACE inhibitors, ARBs, and calcium channel blockers remain effective.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','mcq','A 55-year-old woman on haemodialysis has BP 175/100 mmHg despite multiple antihypertensives. Which is the most important contributor to hypertension in dialysis patients?','["A. Elevated renin only","B. Volume overload due to inadequate fluid removal (interdialytic weight gain)","C. Hyperparathyroidism","D. Anaemia"]','B','Volume overload from inadequate ultrafiltration during dialysis is the primary cause of hypertension in dialysis patients. Achieving dry weight through adequate fluid removal is the most important intervention. Renin-mediated hypertension is secondary; sympathetic overactivation and arterial stiffness also contribute. Dietary sodium restriction between sessions is critical.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','mcq','A 40-year-old man is found to have BP 190/115 mmHg with papilloedema, flame haemorrhages, and creatinine 4.2 mg/dL rising to 6.8 mg/dL over 2 weeks. Urine shows microangiopathic haemolytic anaemia with fragmented cells. What is the diagnosis?','["A. Hypertensive urgency","B. Accelerated hypertension without organ damage","C. Malignant hypertension with hypertensive nephrosclerosis and TMA","D. Primary aldosteronism"]','C','Malignant hypertension (BP >180/120 with end-organ damage) can cause thrombotic microangiopathy (TMA) in the kidney — ''''malignant nephrosclerosis.'''' Features include rapidly declining renal function, MAHA (microangiopathic haemolytic anaemia with schistocytes), thrombocytopaenia, and papilloedema. Urgent BP reduction (IV labetalol or nitroprusside) is required; avoid overly rapid reduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','hard','mcq','A 30-year-old woman presents with hypertension and a renal bruit. CT angiography shows a ''''string of beads'''' appearance in the right renal artery. What is the most likely diagnosis and treatment?','["A. Atherosclerotic renal artery stenosis — treat with statin and ACE inhibitor","B. Polyarteritis nodosa — treat with steroids","C. Renal artery aneurysm — surgical repair","D. Fibromuscular dysplasia — percutaneous transluminal angioplasty"]','D','Fibromuscular dysplasia (FMD) of the renal artery produces the classic ''''string of beads'''' appearance on angiography (alternating stenoses and aneurysms in the medial layer). It predominantly affects young women. Unlike atherosclerotic RAS, FMD responds well to percutaneous transluminal angioplasty (PTA) without stenting, with high cure/improvement rates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','easy','mcq','A patient with CKD and hypertension is found to have serum potassium of 5.8 mEq/L on ACE inhibitor. What is the most appropriate management?','["A. Review and reduce dietary potassium, consider dose reduction or use of potassium binders (e.g., patiromer)","B. Immediately stop ACE inhibitor and switch to amlodipine","C. Add spironolactone to reduce hypertension","D. Increase sodium bicarbonate dose"]','A','Mild to moderate hyperkalaemia on ACE inhibitor in CKD should be managed with dietary potassium restriction, dose optimisation, and novel potassium binders (patiromer, sodium zirconium cyclosilicate) before stopping the ACE inhibitor, which provides significant renoprotection. Avoid adding potassium-sparing diuretics or spironolactone. Stop ACE inhibitor if K+ >6.0 mEq/L or rising rapidly.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Hypertension & the Kidney','medium','mcq','Which combination of antihypertensives is contraindicated in a patient with bilateral renal artery stenosis?','["A. Amlodipine + furosemide","B. ACE inhibitor + ARB (dual renin-angiotensin blockade)","C. Beta-blocker + amlodipine","D. Labetalol + hydralazine"]','B','Dual RAAS blockade (ACE inhibitor + ARB) is generally contraindicated as it increases risk of AKI, hyperkalaemia, and hypotension without additional cardiovascular benefit (ONTARGET trial). Additionally, both ACE inhibitors AND ARBs are contraindicated in bilateral RAS. The combination increases risk of acute renal failure further.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','mcq','A 70-year-old man on furosemide is found to have serum sodium of 126 mEq/L, serum osmolality 258 mOsm/kg, urine osmolality 520 mOsm/kg, and urine sodium 45 mEq/L. What is the most likely cause?','["A. SIADH","B. Psychogenic polydipsia","C. Hypothyroidism","D. Diabetes insipidus"]','A','SIADH is characterised by hyponatraemia with: serum osmolality <275, urine osmolality inappropriately elevated (>100, usually >300), urine sodium >40 mEq/L, and clinically euvolaemic patient. The euvolaemic state excludes heart failure, cirrhosis, and hypovolaemia. Causes include lung cancer (SCLC), CNS disease, drugs (SSRIs, carbamazepine), and surgery.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','mcq','A 55-year-old woman with severe hyponatraemia (Na 108 mEq/L) over 3 days is treated with 3% NaCl. How rapidly should serum sodium be corrected?','["A. Correct to normal within 6 hours","B. No more than 8–10 mEq/L per 24 hours to avoid osmotic demyelination syndrome","C. Correct by 2 mEq/L per hour until symptoms resolve","D. Immediate rapid correction is always safe"]','B','Rapid correction of chronic hyponatraemia (>48 hours) risks osmotic demyelination syndrome (ODS/central pontine myelinolysis) — characterised by flaccid paraparesis, dysphagia, and ''''locked-in'''' syndrome. Safe correction rate: no more than 8–10 mEq/L per 24 hours (or 18 mEq/L per 48 hours). Acute hyponatraemia (<48h) can be corrected more rapidly if symptomatic.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','mcq','A 65-year-old man with chronic kidney disease has serum potassium 6.5 mEq/L. His ECG shows peaked T-waves, widened QRS complexes, and a sinusoidal pattern. What is the first priority in management?','["A. Oral sodium polystyrene sulphonate (Kayexalate)","B. 10% calcium gluconate IV to stabilise the cardiac membrane","C. IV calcium gluconate 10 mL over 10 minutes to stabilise cardiac membrane","D. Oral patiromer 8.4 g"]','C','Hyperkalaemia with ECG changes (peaked T-waves → PR prolongation → QRS widening → sinusoidal pattern → VF) is a cardiac emergency. IV 10% calcium gluconate (10 mL over 2–5 min) immediately stabilises the cardiac membrane without lowering potassium — it is the first step. Then shift K+ into cells (insulin + dextrose, salbutamol, bicarbonate) and remove K+ (kayexalate, diuretics, dialysis).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','hard','mcq','A 25-year-old woman with anorexia nervosa has serum sodium 119 mEq/L, potassium 2.8 mEq/L, and bicarbonate 34 mEq/L. She is haemodynamically stable. What fluid replacement is most appropriate?','["A. 0.9% NaCl 500 mL bolus","B. 3% NaCl infusion","C. 5% dextrose water at 125 mL/h","D. 0.9% NaCl with potassium chloride supplement at controlled rate"]','D','This patient has hyponatraemia + hypokalaemia + metabolic alkalosis — consistent with vomiting/purging behaviour. Hypokalaemia can worsen hyponatraemia and must be corrected simultaneously. 0.9% NaCl with KCl supplementation corrects volume depletion, provides sodium, and corrects potassium. Hypotonic fluids (5% dextrose) would worsen hyponatraemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','mcq','Which ECG change is the earliest sign of hyperkalaemia?','["A. Peaked (tall, narrow, symmetrical) T-waves","B. Prolonged QT interval","C. ST elevation","D. Delta waves"]','A','The earliest ECG manifestation of hyperkalaemia is peaked (tall, narrow, tent-shaped) T-waves, usually when K+ >5.5–6.0 mEq/L. As K+ rises further: PR prolongation → P-wave flattening → QRS widening → sinusoidal pattern → ventricular fibrillation. The QT may shorten in hyperkalaemia (unlike hypocalcaemia which prolongs it).','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','mcq','A 78-year-old confused woman in a nursing home has serum sodium 158 mEq/L, urine output 300 mL/24h, and serum osmolality 330 mOsm/kg. She is not on diuretics and has no diabetes history. What is the most likely cause?','["A. SIADH","B. Hypernatraemia from inadequate free water intake (adipsia/dehydration in elderly)","C. Diabetes insipidus","D. Primary polydipsia"]','B','Hypernatraemia in the elderly is most commonly due to inadequate free water intake — reduced thirst sensation (adipsia), immobility, poor access to fluids. It represents hyperosmolar dehydration. Treatment is gradual free water replacement (oral or 5% dextrose IV), aiming to correct no faster than 10–12 mEq/L per 24 hours to avoid cerebral oedema.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','mcq','A 40-year-old man presents with muscle weakness, constipation, and ECG showing U-waves and flattened T-waves. Serum potassium is 2.6 mEq/L. He takes furosemide. What is the most appropriate treatment?','["A. Oral sodium supplementation","B. IV magnesium sulphate only","C. Oral or IV potassium chloride replacement with attention to magnesium","D. Dietary potassium alone is sufficient"]','C','Hypokalaemia (K+ <3.5 mEq/L) causes ECG changes: U-waves (prominent after T-wave in V2–V4), T-wave flattening, ST depression. Treatment: KCl replacement (oral preferred; IV if severe/symptomatic). Hypomagnesaemia commonly coexists and causes refractory hypokalaemia — correct both. Furosemide causes both kaliuresis and magnesuria.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','hard','mcq','A 60-year-old man with small cell lung cancer develops confusion and serum sodium of 114 mEq/L. Urine osmolality 680 mOsm/kg, urine Na 52 mEq/L. What is the best treatment for this euvolaemic hyponatraemia?','["A. Aggressive IV fluid resuscitation","B. Furosemide alone","C. Hypertonic 3% saline 1 mL/kg/h","D. Fluid restriction ± tolvaptan (V2 receptor antagonist)"]','D','SIADH-associated hyponatraemia (as in SCLC producing ectopic ADH) is treated with: fluid restriction (500–1000 mL/day) as first-line. If refractory or symptomatic, demeclocycline (inhibits ADH action) or tolvaptan/conivaptan (vasopressin V2 receptor antagonists) can be used. 3% NaCl is reserved for severe symptomatic hyponatraemia (seizures, coma). Tolvaptan must be used carefully — risk of overcorrection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','easy','mcq','Which medication is associated with causing hyponatraemia through SIADH?','["A. SSRIs (e.g., fluoxetine)","B. Lithium","C. Furosemide (high dose)","D. Spironolactone"]','A','SSRIs are among the most common drug causes of SIADH and hyponatraemia, particularly in the elderly. Other drugs causing SIADH include carbamazepine, oxcarbazepine, cyclophosphamide, vincristine, and desmopressin. Lithium causes nephrogenic diabetes insipidus (hypernatraemia). Furosemide causes hypovolaemic hyponatraemia, not SIADH.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Electrolyte Disturbances','medium','mcq','A patient with Addison''''s disease has serum Na 128 mEq/L, K+ 5.8 mEq/L, and hypotension. Serum cortisol is low. What is the primary mechanism of hyponatraemia?','["A. Inappropriate ADH secretion only","B. Cortisol deficiency impairs free water excretion AND aldosterone deficiency causes sodium wasting","C. Excessive water intake due to thirst","D. Nephrotic syndrome protein loss"]','B','Addison''''s disease (primary adrenal insufficiency) causes hyponatraemia through two mechanisms: (1) mineralocorticoid (aldosterone) deficiency → sodium wasting with hyperkalaemia; (2) glucocorticoid (cortisol) deficiency → inability to suppress ADH → free water retention. This produces a euvolaemic to hypovolaemic hyponatraemia with hyperkalaemia — a classic combination.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','mcq','A patient''''s ABG shows: pH 7.28, PaCO2 28 mmHg, HCO3 13 mEq/L. What is the primary acid-base disorder?','["A. Metabolic acidosis with appropriate respiratory compensation","B. Respiratory alkalosis","C. Metabolic alkalosis","D. Mixed respiratory and metabolic acidosis"]','A','pH 7.28 = acidosis. Low HCO3 (13) = metabolic acidosis. PaCO2 28 is below normal (40) — the lungs are compensating by blowing off CO2. Expected PaCO2 = 1.5 × HCO3 + 8 ± 2 = 1.5 × 13 + 8 = 27.5 (Winters'''' formula). PaCO2 of 28 is appropriate — this is a simple metabolic acidosis with appropriate respiratory compensation.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','mcq','A 65-year-old diabetic man presents unresponsive. ABG: pH 7.10, PaCO2 18 mmHg, HCO3 6 mEq/L. Serum glucose 42 mmol/L, ketones 3+. Serum Na 136, Cl 98, HCO3 6. What is the anion gap?','["A. 10 mEq/L (normal)","B. 32 mEq/L (elevated — HAGMA)","C. 18 mEq/L (borderline)","D. 6 mEq/L (low)"]','B','Anion gap = Na – (Cl + HCO3) = 136 – (98 + 6) = 32 mEq/L. Normal AG is 8–12 mEq/L. This is a high anion gap metabolic acidosis (HAGMA). With ketonuria and hyperglycaemia, this is diabetic ketoacidosis (DKA). MUDPILES mnemonic: Methanol, Uraemia, DKA, Propylene glycol, Isoniazid, Lactic acidosis, Ethylene glycol, Salicylates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','mcq','A 50-year-old woman with persistent vomiting has: pH 7.52, PaCO2 48 mmHg, HCO3 38 mEq/L. What is the primary disorder and expected compensation?','["A. Respiratory alkalosis with metabolic compensation","B. Metabolic acidosis with respiratory compensation","C. Metabolic alkalosis with appropriate respiratory compensation (hypoventilation)","D. Mixed metabolic alkalosis and respiratory acidosis"]','C','pH 7.52 = alkalosis. HCO3 38 = elevated = metabolic alkalosis. PaCO2 48 (>40) = appropriate hypoventilation. Expected PaCO2 compensation = 0.7 × (HCO3 – 24) + 40 = 0.7 × 14 + 40 = 49.8. Observed PaCO2 = 48, which matches — simple metabolic alkalosis with appropriate compensation. Vomiting causes HCl loss → hypochloraemic metabolic alkalosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','hard','mcq','A 35-year-old man has ABG: pH 7.38, PaCO2 60 mmHg, HCO3 35 mEq/L. What does this represent?','["A. Normal ABG","B. Respiratory acidosis only","C. Metabolic alkalosis only","D. Combined respiratory acidosis + metabolic alkalosis (mixed disorder — pH normal masks both)"]','D','pH 7.38 is normal, but PaCO2 60 (should be 40) = respiratory acidosis, and HCO3 35 (should be 24) = metabolic alkalosis. They cancel each other out to produce a normal pH. Expected metabolic compensation for chronic respiratory acidosis: HCO3 increases by 3.5 mEq/L per 10 mmHg rise in CO2 → 3.5 × 2 = 7 → expected HCO3 = 24 + 7 = 31. Actual HCO3 of 35 is higher than expected, indicating a concurrent metabolic alkalosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','mcq','A patient with diarrhoea has: pH 7.30, PaCO2 32 mmHg, HCO3 15 mEq/L, Na 138, Cl 108. What type of metabolic acidosis is present?','["A. Normal anion gap (hyperchloraemic) metabolic acidosis","B. High anion gap metabolic acidosis","C. Respiratory acidosis","D. Mixed disorder"]','A','AG = 138 – (108 + 15) = 15 mEq/L (normal, using upper limit 12). Wait: AG = 15 mEq/L — borderline; but the question states diarrhoea which causes HCO3 loss with Cl replacement → normal AG (hyperchloraemic) metabolic acidosis. D-MALT: Diarrhoea, RTA, Acetazolamide, early renal failure, Hyperalimentation. The high chloride compensates for the lost bicarbonate.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','mcq','A 70-year-old COPD patient has: pH 7.34, PaCO2 58 mmHg, HCO3 30 mEq/L. What is the most appropriate interpretation?','["A. Acute respiratory acidosis","B. Chronic respiratory acidosis with appropriate metabolic compensation","C. Mixed respiratory and metabolic acidosis","D. Metabolic alkalosis with pseudonormal pH"]','B','In chronic respiratory acidosis, kidneys compensate by retaining HCO3: expected HCO3 = 24 + (3.5 × change in PaCO2/10) = 24 + (3.5 × 1.8) = 24 + 6.3 = 30.3 ≈ 30. The observed HCO3 of 30 matches expected compensation — this is chronic respiratory acidosis (as in COPD) with appropriate renal compensation. pH is mildly acidic as compensation is never complete.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','mcq','A 45-year-old alcoholic man has pH 7.44, PaCO2 40 mmHg, HCO3 28 mEq/L, Na 135, K 2.8, Cl 90. What is the diagnosis?','["A. Normal ABG","B. Respiratory alkalosis","C. Metabolic alkalosis — contraction alkalosis from vomiting and volume depletion","D. SIADH"]','C','pH 7.44 is high-normal (alkalosis). HCO3 28 is elevated with normal PaCO2 → metabolic alkalosis. Low Cl (90) and low K (2.8) indicate vomiting-related loss of HCl with volume contraction. Contraction alkalosis occurs when ECF volume shrinks (from diuretics or vomiting) causing relative HCO3 concentration. Treatment: isotonic saline (chloride-responsive alkalosis). If saline-resistant: consider hyperaldosteronism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','hard','mcq','A 30-year-old woman with type 1 DM has ABG: pH 7.32, PaCO2 22 mmHg, HCO3 11 mEq/L. AG = 24. Delta ratio (delta AG / delta HCO3) = (24-12)/(24-11) = 12/13 = 0.92. What does this delta ratio suggest?','["A. Simple HAGMA only","B. HAGMA + concurrent respiratory alkalosis","C. HAGMA + concurrent metabolic alkalosis","D. HAGMA + concurrent normal AG metabolic acidosis (mixed disorder)"]','D','Delta ratio (Δ AG / Δ HCO3) helps identify mixed disorders in HAGMA. Ratio <1 suggests a co-existing normal AG metabolic acidosis (the HCO3 has fallen more than expected for the AG rise alone). Ratio 1–2 = simple HAGMA; ratio >2 = HAGMA + metabolic alkalosis. Here 0.92 (<1) indicates DKA with a concurrent normal AG metabolic acidosis (e.g., renal tubular acidosis or GI HCO3 loss).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','easy','mcq','Which condition causes a normal anion gap metabolic acidosis (hyperchloraemic)?','["A. Renal tubular acidosis (RTA)","B. Lactic acidosis","C. Diabetic ketoacidosis","D. Ethylene glycol poisoning"]','A','Normal AG (hyperchloraemic) metabolic acidosis is caused by bicarbonate loss or impaired renal acid excretion: RTA types 1, 2, and 4; diarrhoea; early CKD; acetazolamide; fistulae. High AG metabolic acidosis (MUDPILES) involves accumulation of unmeasured anions: lactate, ketones, uraemic acids, toxins.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Acid-Base Disorders','medium','mcq','A 55-year-old woman with CKD stage 4 has pH 7.29, HCO3 14 mEq/L, AG 16 mEq/L. What is the pathophysiology of her acidosis?','["A. Renal tubular acidosis type 1","B. Uraemic acidosis — retention of phosphate, sulphate, and other anions due to reduced GFR","C. Lactic acidosis from metformin","D. Diabetic ketoacidosis"]','B','In advanced CKD (GFR <30), the kidneys fail to excrete fixed acids (phosphate, sulphate, hippurate, urate) — these accumulate as unmeasured anions causing a high AG metabolic acidosis. This is uraemic acidosis. Bicarbonate supplementation (target HCO3 >22) slows CKD progression. In early CKD, normal AG acidosis (impaired NH3 excretion) predominates.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','mcq','A 72-year-old man with CKD stage 5 develops uraemic pericarditis with a pericardial friction rub. What is the most appropriate intervention?','["A. Urgent initiation of haemodialysis","B. NSAIDs and bed rest","C. Pericardiocentesis","D. Colchicine 0.5 mg BD"]','A','Uraemic pericarditis is an absolute indication for urgent dialysis. NSAIDs are nephrotoxic and contraindicated in CKD. Colchicine is used for non-uraemic pericarditis. Pericardiocentesis is reserved for tamponade. The inflammation resolves with adequate dialysis and reduction of uraemic toxins.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','mcq','A 45-year-old woman on haemodialysis develops disequilibrium syndrome during her first dialysis session. She develops headache, nausea, and confusion. What is the mechanism?','["A. Air embolism during dialysis","B. Rapid urea removal creates an osmotic gradient causing cerebral oedema","C. Hyperkalaemia from dialysis fluid","D. Allergic reaction to dialysis membrane"]','B','Dialysis disequilibrium syndrome occurs predominantly in first sessions when urea is removed rapidly. The brain retains urea (idiogenic osmoles) longer than plasma, creating an osmotic gradient that draws water into brain cells → cerebral oedema. Prevention: slow, gradual first dialysis sessions with reduced blood flow rates. Treatment: supportive, mannitol, hypertonic saline.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','mcq','A 55-year-old man with ESRD undergoes successful renal transplantation. His immediate post-operative creatinine is 4.2 mg/dL and he remains dialysis-dependent for 3 weeks. What is the most likely explanation?','["A. Acute rejection — start high-dose steroids","B. Ureteric obstruction","C. Delayed graft function (DGF) from ischaemia-reperfusion injury","D. Chronic rejection"]','C','Delayed graft function (DGF) affects ~25% of deceased donor transplants. It results from ischaemia-reperfusion injury to the donor kidney. The patient requires temporary dialysis while the graft recovers. DGF is distinguished from rejection by a stable (not rising) creatinine trend. Tacrolimus trough levels and ultrasound (to exclude obstruction or vascular issues) guide management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','hard','mcq','A 38-year-old diabetic woman with ESRD is being considered for renal replacement therapy. She has poor vascular access, a history of abdominal surgery, and is a nurse who travels frequently. Which modality is most suitable?','["A. Haemodialysis via arteriovenous fistula","B. Haemodialysis via tunnelled central venous catheter","C. Kidney transplant — only option for young patients","D. Continuous ambulatory peritoneal dialysis (CAPD)"]','D','CAPD is ideal for patients with poor vascular access, those who value independence and the ability to travel, and patients wishing to avoid 3× weekly hospital visits. It provides continuous dialysis replicating physiological clearance. Contraindications include previous extensive abdominal surgery (adhesions reduce peritoneal surface) and inability to perform the technique. PD also better preserves residual renal function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','mcq','What is the most important absolute contraindication to peritoneal dialysis?','["A. Loss of peritoneal membrane function or extensive abdominal adhesions from multiple prior surgeries","B. Diabetes mellitus","C. Hypertension","D. History of myocardial infarction"]','A','Peritoneal dialysis requires an intact, functional peritoneal membrane. Extensive intra-abdominal adhesions (from surgery, peritonitis, or malignancy) preclude effective solute clearance. Other contraindications include: active abdominal hernia, colostomy/ileostomy (infection risk), and inability to perform exchanges. Diabetes is not a contraindication; CAPD allows for intraperitoneal insulin.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','mcq','A patient on CAPD develops sudden-onset abdominal pain, fever, and cloudy peritoneal effluent. WBC in effluent >100/µL with >50% neutrophils. What is the most appropriate immediate management?','["A. Remove peritoneal catheter immediately","B. Intraperitoneal antibiotics (vancomycin + ceftazidime or gentamicin)","C. IV antibiotics only","D. Laparotomy"]','B','Peritonitis is the most common complication of PD. Diagnosis: cloudy effluent + WBC >100/µL (predominantly neutrophils) ± organisms on culture. Treatment: intraperitoneal antibiotics targeting Gram-positive (vancomycin or first-generation cephalosporin) AND Gram-negative organisms. Catheter removal is reserved for refractory cases, fungal peritonitis, or 2+ episodes in 6 months.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','mcq','A haemodialysis patient develops fever and bacteraemia with Staphylococcus aureus. He has a tunnelled central venous catheter for access. What is the appropriate management?','["A. Oral antibiotics for 7 days","B. Lock therapy with antibiotics only","C. Remove the catheter and treat with IV antibiotics for 4–6 weeks (or 2 weeks minimum if bacteraemia clears rapidly)","D. Catheter salvage with systemic antibiotics and no removal"]','C','Catheter-related bloodstream infection (CRBSI) with S. aureus mandates catheter removal due to high risk of seeding (endocarditis, osteomyelitis, septic emboli). IV antibiotics (oxacillin or vancomycin for MRSA) for minimum 2 weeks if uncomplicated, 4–6 weeks if endocarditis or metastatic infection. S. aureus bacteraemia in dialysis patients requires echocardiography to exclude endocarditis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','hard','mcq','A 35-year-old living donor kidney transplant recipient receives tacrolimus, mycophenolate mofetil, and prednisolone. Three months post-transplant, his creatinine rises from 1.2 to 2.8 mg/dL. Biopsy shows tubulitis, interstitial infiltrates, and peritubular capillary C4d deposition. What type of rejection is this?','["A. Hyperacute rejection","B. Chronic allograft nephropathy","C. T-cell mediated acute rejection","D. Antibody-mediated rejection (AMR)"]','D','C4d deposition in peritubular capillaries is the hallmark of antibody-mediated rejection (AMR), reflecting complement activation by donor-specific antibodies (DSA). AMR is more refractory to treatment than T-cell mediated rejection. Treatment: high-dose IV methylprednisolone, plasmapheresis, IVIg, rituximab, ± bortezomib (anti-plasma cell). DSA titres guide monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','easy','mcq','Which of the following is NOT an indication for urgent (emergency) dialysis?','["A. Serum creatinine >500 µmol/L without symptoms","B. Refractory hyperkalaemia K+ >6.5 mEq/L with ECG changes","C. Pulmonary oedema refractory to diuretics","D. Uraemic pericarditis"]','A','Elevated creatinine alone (without symptoms) is not an indication for emergency dialysis. Absolute indications (AEIOU): Acidosis (pH <7.1 refractory), Electrolyte disturbances (hyperkalaemia with ECG changes), Intoxications (ethylene glycol, methanol, salicylates), fluid Overload (pulmonary oedema refractory to diuretics), and Uraemic symptoms (pericarditis, encephalopathy, bleeding). Timing should be based on clinical status.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Replacement Therapy','medium','mcq','A 50-year-old woman with ESRD on haemodialysis asks about transplant options. She has no suitable living donors. What is the approximate wait time for a deceased donor kidney in most settings and what factors affect organ allocation?','["A. 1–3 months; allocation based on blood type only","B. 3–5 years in many countries; allocation based on HLA matching, PRA level, waiting time, and donor-recipient compatibility","C. 6–12 months; allocation based only on age","D. 2 years; allocation based on eGFR alone"]','B','Deceased donor kidney wait times vary by country and blood group (blood group O patients wait longest due to compatibility with all recipients). Allocation in most systems considers HLA matching (to minimise rejection), panel reactive antibody (PRA) level (highly sensitised patients get priority), time on waiting list, geographic proximity, and recipient factors (age, body size). Living donation provides the best outcomes and shortest wait.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','mcq','According to the Ghana STG 2017, what is the first-line treatment for acute uncomplicated cystitis in an adult woman?','["A. Nitrofurantoin 100 mg 6-hourly for 5–7 days","B. Amoxicillin 500 mg TDS for 7 days","C. Metronidazole 400 mg TDS for 5 days","D. Doxycycline 100 mg BD for 7 days"]','A','The Ghana STG 2017 recommends nitrofurantoin 100 mg 6-hourly for 5–7 days as first-line for acute uncomplicated cystitis in adults. It is active against most uropathogens (E. coli, Staph saprophyticus) with low resistance. Second-line: ciprofloxacin 500 mg 12-hourly or cefuroxime 500 mg 12-hourly. Avoid nitrofurantoin in renal impairment (eGFR <30) and at term in pregnancy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','mcq','A 28-year-old pregnant woman (20 weeks gestation) presents with dysuria and frequency. Mid-stream urine (MSU) shows E. coli >10⁵ CFU/mL but she is asymptomatic. What is the appropriate management?','["A. No treatment required — asymptomatic bacteriuria in pregnancy is harmless","B. Treat with cefuroxime oral 500 mg 12-hourly for 5–7 days — asymptomatic bacteriuria in pregnancy increases risk of pyelonephritis and preterm labour","C. Watchful waiting with repeat MSU in 4 weeks","D. Nitrofurantoin only — safe throughout pregnancy"]','B','Asymptomatic bacteriuria in pregnancy is an absolute indication for treatment — it progresses to symptomatic UTI/pyelonephritis in 25–30% of cases and is associated with preterm labour and low birth weight. The Ghana STG recommends cefuroxime for UTI in pregnancy. Nitrofurantoin is avoided in the third trimester (risk of haemolytic anaemia in neonate) and at term.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','mcq','A 35-year-old woman presents with fever 39°C, rigors, right loin pain, vomiting, and pyuria. Urine culture grows E. coli. What is the diagnosis and appropriate treatment?','["A. Acute cystitis — oral nitrofurantoin 5 days","B. Urethritis — azithromycin single dose","C. Acute pyelonephritis — IV ciprofloxacin 400 mg 8-hourly or IV ceftriaxone 1–2 g daily","D. Renal calculus — analgesia and hydration"]','C','Acute pyelonephritis presents with fever, rigors, loin pain/tenderness (CVA tenderness), and urinary symptoms. It is an upper UTI. The Ghana STG recommends IV ciprofloxacin (400 mg 8-12 hourly) or IV ceftriaxone (1–2 g daily) for complicated UTI/pyelonephritis. Step-down to oral when afebrile for 24 hours. Total course: 10–14 days.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','hard','mcq','A 60-year-old diabetic man with recurrent UTIs develops fever, right flank pain, and CT scan showing gas within the renal parenchyma. His blood glucose is 28 mmol/L. What is the most likely diagnosis and management?','["A. Renal abscess — IV antibiotics alone","B. Perinephric abscess — percutaneous drainage","C. Complicated UTI — oral ciprofloxacin 14 days","D. Emphysematous pyelonephritis — IV antibiotics + urgent nephrectomy or percutaneous drainage"]','D','Emphysematous pyelonephritis is a life-threatening necrotising infection of the kidney with gas-forming organisms (most commonly E. coli, Klebsiella) producing gas within the renal parenchyma. It almost exclusively occurs in diabetics. CT is diagnostic. Management: aggressive IV antibiotics, glycaemic control, and emergency nephrectomy or percutaneous drainage (CT Class III/IV cases). Mortality without surgery is very high.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','mcq','What is the most common causative organism of community-acquired UTI?','["A. Escherichia coli (E. coli) — approximately 80% of cases","B. Staphylococcus aureus","C. Pseudomonas aeruginosa","D. Enterococcus faecalis"]','A','E. coli accounts for ~80% of community-acquired UTIs. It possesses virulence factors including type 1 and P fimbriae that enable uroepithelial adhesion. Other common pathogens: Staphylococcus saprophyticus (young sexually active women), Klebsiella, Proteus mirabilis (associated with struvite stones), and Enterococcus.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','mcq','A 25-year-old sexually active woman has her third UTI this year. MSU confirms E. coli each time. What is the most appropriate long-term strategy?','["A. Continuous long-term prophylactic antibiotics indefinitely","B. Post-coital or low-dose continuous prophylaxis (nitrofurantoin 50 mg nocte or trimethoprim 100 mg nocte) for 6 months","C. Self-start therapy with high-dose antibiotics at first symptom","D. Circumcision is recommended"]','B','Recurrent UTI (≥2 in 6 months or ≥3 in 12 months) in women warrants prophylaxis. Options include post-coital single-dose antibiotics (for coitus-related UTIs), low-dose continuous prophylaxis (nitrofurantoin 50–100 mg nocte or trimethoprim 100 mg nocte for 6 months), or patient-initiated self-treatment. Non-antibiotic options: cranberry products (modest benefit), topical oestrogen in post-menopausal women.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','mcq','A mid-stream urine sample shows: leucocytes 3+, nitrites positive, protein trace, no casts. What diagnosis does this support?','["A. Glomerulonephritis","B. Nephrotic syndrome","C. Urinary tract infection","D. Renal tubular acidosis"]','C','Leucocytes (pyuria) + positive nitrites on dipstick strongly predict UTI. Nitrites are produced by bacterial reduction of nitrate (most Gram-negatives, not Gram-positives like Enterococcus or Staph). Pyuria (>10 WBC/hpf on microscopy) indicates infection. Red cell casts indicate glomerulonephritis. The absence of casts and heavy proteinuria makes nephrotic/glomerular disease unlikely.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','hard','mcq','A 70-year-old man with an indwelling urinary catheter for 5 days has a positive urine culture (Klebsiella 10⁵ CFU/mL) but no fever, no symptoms, and no leucocytosis. What is the most appropriate action?','["A. Treat immediately with IV gentamicin","B. Treat with oral ciprofloxacin for 7 days","C. Change catheter and re-culture","D. No treatment required — catheter-associated asymptomatic bacteriuria does not require antibiotics"]','D','Catheter-associated asymptomatic bacteriuria (CAASB) should NOT be treated with antibiotics (except before urological procedures). Treatment increases antibiotic resistance and does not improve outcomes. Remove the catheter as soon as no longer needed. Treatment is indicated only if symptomatic (fever, rigors, flank pain) or before urological instrumentation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','easy','mcq','Which investigation is most specific for confirming the diagnosis of UTI?','["A. Mid-stream urine culture and sensitivity showing ≥10⁵ CFU/mL of a single pathogen","B. Dipstick positive for leucocytes alone","C. Serum CRP elevation","D. Ultrasound showing increased renal echogenicity"]','A','Mid-stream urine (MSU) culture showing ≥10⁵ colony-forming units/mL of a single uropathogen is the gold standard for diagnosing UTI. Dipstick is useful for rapid screening (sensitivity ~75%, specificity ~82% for nitrites). Culture and sensitivity guides targeted antibiotic therapy. The Ghana STG emphasises MSU culture in all UTI patients.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','UTI & Pyelonephritis','medium','mcq','A 50-year-old man with recurrent UTIs and Proteus mirabilis on culture develops haematuria and right loin pain. KUB X-ray shows a staghorn calculus. What type of stone is this?','["A. Calcium oxalate stone","B. Struvite (magnesium ammonium phosphate) stone","C. Uric acid stone","D. Cystine stone"]','B','Struvite (triple phosphate / magnesium ammonium phosphate) stones form in the setting of infection with urease-producing organisms (Proteus, Klebsiella, Pseudomonas, Ureaplasma). Urease splits urea → ammonia → alkaline urine → precipitation of struvite. Staghorn calculi filling the renal pelvis and calyces are typical. Treatment requires stone removal AND eradication of infection.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Ghana STG 2017; Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','mcq','A 35-year-old man presents with severe colicky right loin-to-groin pain, nausea, and haematuria. Which imaging modality is the gold standard for diagnosing renal calculi?','["A. Non-contrast CT KUB (NCCT)","B. Plain X-ray (KUB film)","C. Intravenous urogram (IVU)","D. Renal ultrasound alone"]','A','Non-contrast CT KUB (kidneys-ureters-bladder) is the gold standard for renal calculi — sensitivity >95%, specificity >98%. It detects all stone types including uric acid stones (radiolucent on plain X-ray). Plain X-ray detects only radiopaque stones (calcium-containing, ~75% of stones) and misses many. Ultrasound is useful in pregnancy/children; IVU is largely replaced by CT.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','mcq','A 5 mm ureteric stone is confirmed on CT KUB. The patient''''s pain is controlled and he is systemically well. What is the most appropriate initial management?','["A. Emergency ureteroscopy","B. Conservative management — analgesia (diclofenac), hydration, alpha-blocker (tamsulosin 0.4 mg daily) for medical expulsive therapy","C. Extracorporeal shock wave lithotripsy (ESWL) immediately","D. Nephrostomy tube insertion"]','B','Stones ≤5 mm have a 68% spontaneous passage rate. Medical expulsive therapy with alpha-blockers (tamsulosin) relaxes ureteric smooth muscle to facilitate passage. Diclofenac (NSAID) is the preferred analgesic (also reduces ureteric oedema). High fluid intake is encouraged. Indications for intervention: obstruction + infection (emergency), anuria, pain refractory to analgesia, stone >10 mm (unlikely to pass).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','mcq','Which type of kidney stone is radiolucent on plain X-ray and requires CT for diagnosis?','["A. Calcium oxalate","B. Calcium phosphate (brushite)","C. Uric acid stone","D. Struvite (triple phosphate)"]','C','Uric acid stones are radiolucent (invisible on plain X-ray/KUB) because they lack calcium. All other common stone types (calcium oxalate, calcium phosphate, struvite) are radiopaque. Uric acid stones form in acidic urine (pH <5.5) and are associated with gout, myeloproliferative disorders, and high purine diets. They can be dissolved with urinary alkalinisation (potassium citrate to achieve urine pH 6.5–7.0).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','hard','mcq','A 45-year-old woman with recurrent calcium oxalate stones has hypercalciuria, normal serum calcium, normal PTH, and 24-hour urine calcium >300 mg/day. What is the most appropriate preventive strategy?','["A. Low calcium diet to reduce urinary calcium","B. High vitamin D supplementation","C. Encourage high dietary oxalate foods","D. Thiazide diuretic (hydrochlorothiazide) + dietary calcium normalisation (aim 1000–1200 mg/day from food)"]','D','Idiopathic hypercalciuria is the most common metabolic risk factor for calcium oxalate stones. Thiazide diuretics reduce urinary calcium by enhancing tubular reabsorption. Paradoxically, dietary calcium should NOT be severely restricted — adequate calcium binds oxalate in the gut, reducing urinary oxalate. Other measures: increased fluid intake (>2.5 L/day), reduced sodium and animal protein. Citrate supplementation (potassium citrate) inhibits crystallisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','mcq','A patient has recurrent calcium oxalate stones. Which dietary modification has the strongest evidence for stone prevention?','["A. High fluid intake (≥2.5 L urine output/day)","B. Strict low-protein vegan diet","C. Low fluid intake to concentrate urine","D. High-dose calcium supplements"]','A','The single most effective preventive measure for all types of renal stones is high fluid intake (aim urine output >2.5 L/day; urine dilution reduces supersaturation). Additional measures: reduced sodium (<2300 mg/day reduces calciuria), reduced animal protein (reduces uric acid and calciuria), moderate dietary calcium from food. High-dose calcium supplements may actually increase stone risk.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','mcq','A 12 mm renal pelvis stone is identified in a patient with recurrent infections. What treatment is most appropriate?','["A. Medical expulsive therapy with tamsulosin","B. Percutaneous nephrolithotomy (PCNL)","C. Extracorporeal shock wave lithotripsy (ESWL)","D. Conservative management — likely to pass spontaneously"]','B','Stones >10 mm rarely pass spontaneously. For stones >20 mm or staghorn calculi, PCNL is the treatment of choice. For stones 10–20 mm in the renal pelvis, PCNL or ESWL may be used depending on stone composition and location. ESWL works best for soft stones (calcium oxalate dihydrate) in good position. Ureteroscopy (URS) with laser lithotripsy is preferred for ureteric stones. Stones >2 cm in a lower pole may not clear with ESWL.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','mcq','A 40-year-old man with gout has his second uric acid stone. Serum uric acid is elevated. What is the medical management?','["A. Allopurinol alone without alkalization","B. Indometacin for acute gout only","C. Urinary alkalinisation with potassium citrate (target pH 6.5–7.0) + allopurinol + high fluid intake","D. Cholchicine indefinitely"]','C','Uric acid stone prevention combines: (1) urinary alkalinisation with potassium citrate (target urine pH 6.5–7.0 — at this pH uric acid dissolves); (2) allopurinol to reduce uric acid production if hyperuricaemia present or high stone recurrence; (3) high fluid intake (>2.5 L/day); (4) low-purine diet. Existing uric acid stones can be dissolved with aggressive alkalinisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','hard','mcq','A 30-year-old woman with recurrent bilateral staghorn calculi has amino acid chromatography showing elevated cystine in urine. What is the diagnosis and treatment?','["A. Struvite stones from recurrent infection — treat infection","B. Hyperparathyroidism — measure PTH","C. RTA type 1 — give sodium bicarbonate","D. Cystinuria (defect in dibasic amino acid transport) — high fluid intake, urinary alkalinisation, D-penicillamine or tiopronin"]','D','Cystinuria is an autosomal recessive defect in SLC3A1/SLC7A9 genes encoding cystine-dibasic amino acid transporter, causing accumulation of cystine (poorly soluble) in urine forming recurrent bilateral radiopaque hexagonal cystine crystals. Treatment: extreme fluid intake (>3 L/day), alkalinisation (pH >7.5), and chelating agents (D-penicillamine or tiopronin) that form more soluble cystine-thiol complexes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','easy','mcq','A patient presents with flank pain and haematuria. Which urinalysis finding is most consistent with renal colic from a stone?','["A. Microhaematuria (RBCs on dipstick/microscopy) without casts","B. Red cell casts","C. White cell casts","D. Oval fat bodies"]','A','Microhaematuria without casts is the classic urinalysis finding in renal calculi — caused by direct trauma to the urothelium. Red cell casts indicate glomerular bleeding (glomerulonephritis). White cell casts indicate pyelonephritis or interstitial nephritis. Oval fat bodies (lipid-laden tubular cells) indicate nephrotic syndrome.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Renal Calculi — Clinical Management','medium','mcq','A 55-year-old man with hyperparathyroidism has recurrent calcium phosphate (brushite) stones and serum calcium 2.8 mmol/L. What is the underlying mechanism and definitive treatment?','["A. Renal tubular acidosis — treat with bicarbonate","B. Primary hyperparathyroidism causing hypercalcaemia and hypercalciuria — parathyroidectomy is definitive","C. Excessive vitamin D intake — reduce supplements","D. Sarcoidosis — treat with steroids"]','B','Primary hyperparathyroidism is a major secondary cause of calcium stones. Elevated PTH causes hypercalcaemia, hypercalciuria (calcium filtered load exceeds tubular reabsorption), and alkaline urine (PTH inhibits tubular bicarbonate reabsorption). This promotes calcium phosphate stone formation. Definitive treatment is surgical parathyroidectomy. Calcium phosphate stones are also associated with distal RTA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','mcq','A 55-year-old man with hepatitis B infection develops proteinuria 5 g/24h and hypoalbuminaemia. Renal biopsy shows thickened GBM with granular IgG and C3 deposits in a ''''spike and dome'''' pattern. What is the diagnosis?','["A. Membranous nephropathy secondary to hepatitis B","B. Minimal change disease","C. IgA nephropathy","D. FSGS"]','A','Membranous nephropathy is the most common cause of nephrotic syndrome in adults. The ''''spike and dome'''' pattern on silver stain represents subepithelial immune deposits with GBM reaction. Secondary causes include hepatitis B, hepatitis C, SLE, malignancy, and drugs (NSAIDs, gold). In primary MN, anti-PLA2R antibodies are present in 70%. Hepatitis B-associated MN is a major cause in endemic areas.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','mcq','A 12-year-old boy with steroid-resistant nephrotic syndrome has renal biopsy showing segmental areas of sclerosis in some (not all) glomeruli, with effacement of podocyte foot processes. What is the diagnosis and prognosis?','["A. Minimal change disease — excellent prognosis","B. Focal segmental glomerulosclerosis (FSGS) — risk of ESRD","C. Membranous nephropathy — good prognosis","D. Mesangial proliferative GN"]','B','FSGS is defined by focal (<50% glomeruli) and segmental (<50% of glomerular tuft) sclerosis. It is the most common primary glomerular cause of ESRD in adults. Steroid resistance occurs in ~80% of idiopathic FSGS. Poor prognostic features: heavy proteinuria at presentation, impaired renal function, steroid resistance. Treatment: calcineurin inhibitors (cyclosporine or tacrolimus). Genetic FSGS (podocin/NPHS2 mutations) does not respond to immunosuppression.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','mcq','A 40-year-old man undergoes renal biopsy for nephrotic syndrome. The biopsy shows mesangial and endocapillary proliferation with lobular accentuation, and C3 and IgG deposits in mesangium and capillary walls. IF shows ''''tram-track'''' duplication of GBM. What is the diagnosis?','["A. IgA nephropathy","B. Focal segmental glomerulosclerosis","C. Membranoproliferative glomerulonephritis (MPGN)","D. Anti-GBM disease"]','C','MPGN (Type I) shows mesangial interposition between endothelial cells and GBM, creating the ''''tram-track'''' or ''''double contour'''' appearance on silver stain. It may present with nephrotic and/or nephritic features. Causes include chronic infections (hepatitis C, HIV, cryoglobulinaemia), autoimmune diseases, and MGUS. Low C3 is characteristic. Management addresses the underlying cause.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','hard','mcq','A 35-year-old man with haematuria, proteinuria, and deafness undergoes renal biopsy. EM shows irregular alternating thickening and thinning of the GBM (''''basketweave''''). Genetic testing confirms a pathogenic COL4A5 variant. What is the most important prognostic factor?','["A. Level of proteinuria at presentation","B. Presence of deafness","C. Complement levels","D. Whether the mutation affects the COL4A5 gene (X-linked Alport) — truncating mutations carry worst prognosis (ESRD by age 25 in males)"]','D','In X-linked Alport syndrome (COL4A5 mutations), the type and location of mutation predicts prognosis. Truncating mutations (nonsense, frameshift) → ESRD by age 21–25 in males. Missense mutations → ESRD by ~30–40 years. Female carriers can develop significant renal disease. ACE inhibitors slow progression and may delay ESRD onset. Genetic counselling is essential. Allport syndrome does not recur in transplanted kidneys as the new kidney has normal collagen IV.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','mcq','Which investigation result provides the strongest indication for renal biopsy in a patient with suspected glomerular disease?','["A. Nephrotic syndrome in an adult, or unexplained AKI or CKD with active urinary sediment","B. Microhaematuria alone in a 20-year-old","C. Mildly elevated serum creatinine 1.2 mg/dL with no proteinuria","D. Positive urine dipstick for protein in a diabetic with 20-year history of diabetes"]','A','Renal biopsy indications include: nephrotic syndrome in adults (to determine cause before immunosuppression), rapidly progressive GN, AKI of unknown cause, significant proteinuria (>1 g/day) without an obvious explanation, and suspected systemic diseases with renal involvement (lupus, vasculitis). Isolated microhaematuria in a young person (likely IgA nephropathy or thin BM disease) may not require biopsy. Diabetic nephropathy with classic history rarely needs biopsy.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','mcq','A 28-year-old woman with lupus presents with haematuria, proteinuria 4 g/24h, creatinine rising to 2.5 mg/dL over 6 weeks, and low C3/C4. Renal biopsy shows diffuse proliferative changes (ISN Class IV). What is the induction therapy?','["A. Prednisolone alone 60 mg/day","B. Mycophenolate mofetil 2–3 g/day + IV pulse methylprednisolone (then oral prednisolone)","C. Azathioprine + prednisolone","D. Tacrolimus alone"]','B','ISN Class IV lupus nephritis (diffuse proliferative) requires induction immunosuppression: EURO-Lupus regimen (low-dose IV cyclophosphamide 500 mg fortnightly × 6 doses) or mycophenolate mofetil (MMF 2–3 g/day) + high-dose steroids. MMF is preferred in women of childbearing age and in non-European populations. Maintenance: MMF 1–2 g/day + low-dose prednisolone. Monitor anti-dsDNA and complement for disease activity.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','mcq','A 50-year-old man has been on oral gold therapy for rheumatoid arthritis for 2 years. He develops proteinuria 3.5 g/24h. Renal biopsy shows subepithelial deposits with a ''''spike and dome'''' pattern. What is the most appropriate management?','["A. Add prednisolone 40 mg/day","B. Continue gold and add ACE inhibitor","C. Stop gold therapy — drug-induced membranous nephropathy usually remits spontaneously","D. Start cyclophosphamide immediately"]','C','Gold therapy (and penicillamine) is a well-established cause of drug-induced membranous nephropathy. The treatment is to withdraw the causative drug — most cases remit spontaneously over months after discontinuation. Additional immunosuppression is not usually required for drug-induced MN. ACE inhibitor can be added to reduce proteinuria while awaiting remission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','hard','mcq','A 65-year-old man with IgG kappa MGUS develops nephrotic syndrome. Biopsy shows amorphous deposits in the mesangium and GBM staining positive with Congo red and displaying apple-green birefringence under polarised light. What is the diagnosis?','["A. MPGN Type I","B. Light chain deposition disease","C. Fibrillary glomerulonephritis","D. Renal amyloidosis (AL-type amyloid from plasma cell dyscrasia)"]','D','AL amyloidosis (primary amyloidosis) from plasma cell dyscrasias (MGUS, myeloma) deposits amyloid fibrils in the kidney. Congo red staining with apple-green birefringence under polarised light is pathognomonic of amyloid. AL type contains immunoglobulin light chains (kappa or lambda). Clinical features: nephrotic syndrome, hepatomegaly, macroglossia, peripheral neuropathy, cardiomyopathy. Treatment: chemotherapy targeting the plasma cell clone (bortezomib-based regimens).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','easy','mcq','Which immunosuppressive drug is avoided in pregnancy due to teratogenicity?','["A. Mycophenolate mofetil (MMF)","B. Prednisolone","C. Azathioprine","D. Tacrolimus"]','A','Mycophenolate mofetil (MMF) is absolutely contraindicated in pregnancy — it causes first-trimester pregnancy loss and congenital malformations (microtia, coloboma, facial clefts). Women of childbearing age should use two forms of contraception. Switch to azathioprine (safer in pregnancy) before conception. Prednisolone and tacrolimus are used in pregnancy with monitoring.','universal',false,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Clinicals','Glomerular Disease — Clinical Approach','medium','mcq','A 45-year-old woman with SLE goes into clinical remission of Class IV lupus nephritis after induction. What is the recommended maintenance immunosuppression?','["A. Cyclophosphamide monthly pulses indefinitely","B. Mycophenolate mofetil 1–2 g/day + low-dose prednisolone ≤7.5 mg/day for minimum 3 years","C. Prednisolone 40 mg/day long-term","D. Hydroxychloroquine as the only maintenance agent"]','B','Maintenance therapy for Class III/IV lupus nephritis: mycophenolate mofetil 1–2 g/day + low-dose steroids for minimum 3 years (European League Against Rheumatism/ACR guidelines). Hydroxychloroquine should be added in all lupus nephritis patients (reduces flares, cardiovascular risk, and mortality). Cyclophosphamide is not used for maintenance due to cumulative toxicity (infections, malignancy, gonadal toxicity).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Harrison''s Principles of Internal Medicine 20th Ed');
